	// Initialize C: C[i][j] = (i * j + 2) % m / m
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / (num_t)m_len;
	});
