	// so that we can naturally index A[j][k] alongside C[i][j].
	auto A_row_as_j = A ^ noarr::rename<'i', 'j'>();

	// C: i x j (N x N)
	// A: i x k (N x M)
	// Form C := alpha * A * A^T + beta * C, but only the lower triangle (j <= i)
