	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// lengths corresponding to 'n' and 'm' in the original C code
	auto n = C | get_length<'i'>(); // N
	auto m = A | get_length<'k'>(); // M

	// A[i][k] = ((i*k+1) % n) / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n) / n;
	});

	// C[i][j] = ((i*j+2) % m) / m;
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m) / m;
	});
}

// computation kernel
// Form C := alpha * A * A^T + beta * C
// A: i x k  (N x M)
// C: i x j  (N x N), lower triangle (j <= i) is updated
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	// View of A with its row-dimension renamed from 'i' to 'j'
	// so that we can express A[j][k] as A_jk[state] while A[i][k] is A[state].
	auto A_jk = A ^ noarr::rename<'i', 'j'>();

#pragma scop
	// Outer loop over i
	traverser(C, A).template for_dims<'i'>([=](auto trav_i) {
		// First: C[i][j] *= beta for j = 0..i
		trav_i.template for_each<'j'>([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			if (j <= i)
				C[state] *= beta;
		});

		// Then: for k = 0..M-1 and j = 0..i:
		//   C[i][j] += alpha * A[i][k] * A[j][k];
		trav_i.template for_dims<'k'>([=](auto trav_k) {
			trav_k.template for_each<'j'>([=](auto state) {
				auto [i, j] = get_indices<'i', 'j'>(state);
				if (j <= i)
					C[state] += alpha * A[state] * A_jk[state];
			});
		});
	});
#pragma endscop
